// C5: solo se aceptan avisos con el token de Zabbix.
const entrada = $input.first().json;
const cab = entrada.headers || {};
const b = entrada.body || {};
const inicio = Date.now();   // para medir cuánto tarda la ejecución
if (!cab['x-zabbix-token'] || cab['x-zabbix-token'] !== $env.WEBHOOK_TOKEN) {
  return [{ json: { accion: 'rechazar', motivo: 'token inválido: aviso descartado', event_id: null, rechazada: true, inicio } }];
}

let tags = [];
try { tags = typeof b.tags === 'string' ? JSON.parse(b.tags) : (b.tags || []); } catch (e) { tags = []; }
const tag = (n) => (tags.find((t) => t.tag === n) || {}).value;
const remediation = tag('remediation') || 'none';
const target = tag('target') || '';

// C1: lista cerrada. El comando sale de esta tabla, NUNCA del texto recibido.
const PERMITIDOS = {
  'restart-container': { 'msmotos-app': 'sudo /usr/bin/docker start msmotos-app' },
  'restart-service': { 'nginx': 'sudo /usr/bin/systemctl restart nginx' },
  // En Windows la cuenta de n8n solo acepta este pedido (infra/vm-app-win/preparar-n8n-ops.ps1).
  'restart-service-win': { 'MSMotos': 'start MSMotos' },
};
// Red (IP2-86): solo los puertos de acceso de SW1, Fa0/1 a Fa0/20. Los enlaces de gestión
// (Gi0/1, Gi0/2, la WAN del router) nunca traen una acción: solo alertan (control C8).
const PUERTO = /^sw1:(Fa0\/(?:[1-9]|1[0-9]|20))$/;
// Acciones que se ejecutan en vm-app-win; el resto va a vm-app.
const EN_WINDOWS = ['restart-service-win'];

const esProblema = String(b.event_value) === '1';
let accion = 'notificar';
let comando = null;
let motivo = '';
let rechazada = false;

if (esProblema && remediation !== 'none') {
  const puerto = PUERTO.exec(target);
  comando = remediation === 'restart-interface'
    ? (puerto ? `reiniciar ${puerto[1]}` : null)
    : (PERMITIDOS[remediation] || {})[target] || null;
  if (!comando) {
    motivo = `acción rechazada: ${remediation}/${target} no está en la lista permitida`;
    rechazada = true;
  } else {
    // C2 y C3: máximo 3 intentos por objetivo cada 10 minutos; luego se escala a una persona.
    const estado = $getWorkflowStaticData('global');
    const clave = `${remediation}:${target}`;
    const ahora = Date.now();
    const recientes = (estado[clave] || []).filter((t) => ahora - t < 10 * 60 * 1000);
    if (recientes.length >= 3) {
      accion = 'escalar';
      comando = null;
      motivo = 'recuperación automática agotada (3 intentos en 10 min): requiere intervención humana';
    } else {
      recientes.push(ahora);
      estado[clave] = recientes;
      accion = 'recuperar';
      motivo = `intento ${recientes.length} de 3`;
    }
  }
}

return [{ json: {
  accion, motivo, comando, remediation, target,
  event_id: b.event_id, event_value: String(b.event_value), severity: b.severity,
  host: b.host, trigger: b.trigger, time: b.time, opdata: b.opdata,
  duration: b.duration, rechazada, inicio,
  windows: EN_WINDOWS.includes(remediation),
  red: remediation === 'restart-interface',
} }];

const d = $('Validar y decidir').first().json;
const r = $input.first().json;
const ok = r.code === 0 && !r.error;
// Lo que respondió el equipo (por ejemplo, en qué estado quedó el puerto).
const salida = String(r.stdout || '').trim();
const detalle = ok ? (salida || 'comando ejecutado') : `falló: ${(salida || r.stderr || r.error?.message || r.error || 'sin detalle')}`;
return [{ json: {
  ...d,
  resultado: ok ? 'OK' : 'FALLO',
  salida,
  mensaje: `🔧 [${d.severity}] ${d.trigger} · ${d.host} · recuperación automática (${d.motivo}): ${detalle}`,
} }];

const d = $input.first().json;
const icono = d.accion === 'rechazar' ? '⛔ RECHAZADO'
  : d.event_value === '0' ? '✅ RESUELTO'
  : d.accion === 'escalar' ? '🚨 ESCALAR A HUMANO'
  : '🔴 PROBLEMA';
return [{ json: {
  ...d,
  mensaje: `${icono} [${d.severity || '-'}] ${d.trigger || ''} · ${d.host || ''} · ${d.time || ''}${d.motivo ? ' · ' + d.motivo : ''}`,
} }];

// Arma el aviso para una persona (IP2-51). No envía nada: solo decide si corresponde
// avisar y con qué texto. Sin bot configurado, o si el evento es de poca importancia,
// deja avisar = false y el flujo termina ahí.
const d = $input.first().json;
const configurado = Boolean($env.TELEGRAM_BOT_TOKEN && $env.TELEGRAM_CHAT_ID);

// Se avisa de los triggers del proyecto (T01, T06...) y de todo lo que sea Average o más.
const graves = ['Average', 'High', 'Disaster'];
const delProyecto = /^T[0-9]{2}/.test(String(d.trigger || ''));
const importante = delProyecto || graves.includes(d.severity);

const resuelto = d.event_value === '0';
const titulo = resuelto ? '✅ RESUELTO'
  : d.accion === 'escalar' ? '🚨 REQUIERE UNA PERSONA'
  : d.accion === 'recuperar' && d.resultado === 'FALLO' ? '🚨 LA RECUPERACIÓN FALLÓ: REQUIERE UNA PERSONA'
  : d.accion === 'recuperar' ? '🔧 RECUPERACIÓN AUTOMÁTICA'
  : '🔴 PROBLEMA';

const lineas = [
  `${titulo} [${d.severity || '-'}]`,
  String(d.trigger || ''),
  `Host: ${d.host || '-'}`,
  `Hora: ${d.time || '-'}`,
];
if (d.opdata) lineas.push(`Valor: ${d.opdata}`);
if (d.accion === 'recuperar') {
  lineas.push(`Acción: ${d.comando} (${d.motivo})`);
  lineas.push(`Resultado: ${d.resultado || '-'}`);
  if (d.salida) lineas.push(`Detalle: ${d.salida}`);
} else if (d.motivo) {
  lineas.push(`Detalle: ${d.motivo}`);
} else if (!resuelto) {
  lineas.push('Acción automática: ninguna, requiere revisión');
}
lineas.push(`Evento Zabbix: #${d.event_id}`);

return [{ json: {
  ...d,
  avisar: configurado && importante,
  motivo_aviso: !configurado ? 'Telegram sin configurar' : importante ? 'se avisa' : 'severidad baja: no se avisa',
  aviso: lineas.join(String.fromCharCode(10)),
} }];

// Arma lo que n8n reporta a Zabbix de esta ejecución (IP2-77). Alimenta el tablero de
// Automatización. Cada dato es un evento: el tablero los suma en el periodo elegido.
const d = $input.first().json;
const TIPOS = { 'restart-service': 'servicio', 'restart-container': 'contenedor', 'restart-service-win': 'servicio-win', 'restart-interface': 'interfaz' };
const tipo = TIPOS[d.remediation];
const ahora = Math.floor(Date.now() / 1000);
const valores = [];
const agregar = (key, value) => valores.push({ host: 'automatizacion', key, value: String(value), clock: ahora });

if (d.rechazada) agregar('n8n.rejected', 1);
if (d.accion === 'escalar') agregar('n8n.escalated', 1);
if (d.accion === 'recuperar' && tipo) {
  const ok = d.resultado === 'OK';
  agregar(`n8n.exec.status[${tipo}]`, ok ? 1 : 0);
  agregar(`n8n.exec.duration[${tipo}]`, ((Date.now() - d.inicio) / 1000).toFixed(1));
  agregar(`n8n.exec.action[${tipo}]`, `${d.comando} (${ok ? 'OK' : 'falló'}, ${d.motivo})`);
  if (ok) agregar(`n8n.recovery.count[${tipo}]`, 1);
}
// Al cerrarse un problema que tiene recuperación automática: cuánto duró, de la
// detección al cierre. Zabbix lo manda como texto, por ejemplo "1m 23s".
if (d.event_value === '0' && tipo) {
  const UNIDAD = { d: 86400, h: 3600, m: 60, s: 1 };
  let segundos = 0;
  for (const [, n, u] of String(d.duration || '').matchAll(/(\d+)\s*([dhms])/g)) segundos += Number(n) * UNIDAD[u];
  if (segundos > 0) agregar(`n8n.recovery.seconds[${tipo}]`, segundos);
}
// Sin nada que reportar, el flujo termina aquí.
return valores.length ? [{ json: { valores } }] : [];
